<?php require 'config.php';$stock=$pdo->query('SELECT p.name,s.quantity_available FROM stock s JOIN produce p ON p.produce_id=s.produce_id ORDER BY p.name')->fetchAll();$deliveries=(float)$pdo->query('SELECT COALESCE(SUM(quantity),0) FROM deliveries')->fetchColumn();$orders=(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();$dispatches=(int)$pdo->query('SELECT COUNT(*) FROM dispatches')->fetchColumn();?>
<!doctype html><html><head><meta charset="utf-8"><title>Reports</title><link rel="stylesheet" href="style.css"></head><body><header><h1>Reports</h1><nav><a href="index.php">Dashboard</a><a href="farmers.php">Farmers</a><a href="deliveries.php">Deliveries</a><a href="orders.php">Orders</a><a href="dispatches.php">Dispatches</a></nav></header><main><h2>Summary</h2><div class="cards"><div class="card"><h3>Total delivery quantity</h3><p><?=number_format($deliveries,2)?> kg</p></div><div class="card"><h3>Orders</h3><p><?=$orders?></p></div><div class="card"><h3>Dispatch records</h3><p><?=$dispatches?></p></div></div><h2>Stock Report</h2><table><tr><th>Produce</th><th>Available kg</th></tr><?php foreach($stock as $s):?><tr><td><?=htmlspecialchars($s['name'])?></td><td><?=$s['quantity_available']?></td></tr><?php endforeach;?></table><p>Report values reflect records stored in the current database.</p></main></body></html>
